'use strict';
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
let toastTimer;
function toast(message) { const el = $('#toast'); el.textContent = message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 3500); }
function downloadFile(name, content, type) { const blob = new Blob([content], {type}); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = name; document.body.append(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); toast('Your free demo is ready. Enjoy your new era.'); }
function showDialog(dialog) { dialog.showModal(); document.body.style.overflow = 'hidden'; }
$$('dialog').forEach(dialog => { $('.close-dialog', dialog).addEventListener('click', () => dialog.close()); dialog.addEventListener('close', () => { document.body.style.overflow = ''; }); dialog.addEventListener('click', event => { if (event.target !== dialog) return; const r = dialog.getBoundingClientRect(); if (event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom) dialog.close(); }); });
$('.menu-toggle').addEventListener('click', () => { const open = $('.nav').classList.toggle('open'); $('.menu-toggle').setAttribute('aria-expanded', String(open)); $('.menu-toggle').setAttribute('aria-label', open ? 'Close navigation' : 'Open navigation'); });
$$('.nav a').forEach(a => a.addEventListener('click', () => { $('.nav').classList.remove('open'); $('.menu-toggle').setAttribute('aria-expanded', 'false'); $('.menu-toggle').setAttribute('aria-label', 'Open navigation'); }));
$$('.filter').forEach(button => button.addEventListener('click', () => { $$('.filter').forEach(b => { b.classList.toggle('active', b === button); b.setAttribute('aria-pressed', String(b === button)); }); $$('.product').forEach(p => { p.hidden = button.dataset.filter !== 'all' && p.dataset.category !== button.dataset.filter; }); }));
