let currentProduct = 'logos';
$$('[data-product]').forEach(button => button.addEventListener('click', () => { currentProduct = button.dataset.product; const p = products[currentProduct]; $('#product-dialog-title').textContent = p.title; $('#product-dialog-category').textContent = p.category; $('#product-dialog-description').textContent = p.description; $('#product-dialog-list').replaceChildren(...p.items.map(text => { const li = document.createElement('li'); li.textContent = text; return li; })); const art = $('#product-dialog-art'); art.replaceChildren(); if (p.art === 'logos') { const img = document.createElement('img'); img.src = 'assets/instant-icon.svg'; img.alt = 'Almost Famous editable logo demo'; art.append(img); art.style.background = '#e5e9f6'; } else if (p.art === 'content') { art.append($('.content-preview').cloneNode(true)); art.style.background = '#243de8'; } else { art.append($('.mini-book').cloneNode(true)); art.style.background = '#e6ebd7'; } showDialog($('#product-dialog')); }));
$('#product-download').addEventListener('click', async () => { const p = products[currentProduct]; try { let content; if (currentProduct === 'logos') { const r = await fetch('assets/instant-icon.svg'); if (!r.ok) throw new Error('Unavailable'); content = await r.text(); } else if (currentProduct === 'content') content = 'MAIN CHARACTER CAPTIONS\nA free original creative demo by JayNova Brands\n\nSatirical, AI-style copy. No live AI service or earnings claims.\n\n' + captions.map((c, i) => `${i + 1}. ${c}`).join('\n\n') + '\n\nOriginal demo text. Free to use and edit, non-exclusively, for personal or commercial projects. No warranty.\n'; else content = playbook; downloadFile(p.filename, content, p.mime); } catch { toast('The file could not load. Please try again.'); } });
function escapeXml(value) { return value.replace(/[<>&"']/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c])); }
let brandSvg = '', brandCaption = '';
const moods = {bold:{bg:'#d6f34b',fg:'#243de8',tag:'UNREASONABLY CONFIDENT.',caption:'has entered the chat. Big ideas. Bigger type. An unreasonable amount of confidence.'},minimal:{bg:'#171b25',fg:'#f8f9fc',tag:'LESS NOISE. MORE PRESENCE.',caption:'is keeping it simple. Good ideas do not need to shout. The design can do the talking.'},playful:{bg:'#243de8',fg:'#d6f34b',tag:'SERIOUS ABOUT THE NONSENSE.',caption:'is in its new era. A little extra. Very online. Professionally unserious.'}};
function generateBrand() { const input = $('#brand-name'); const name = input.value.trim().replace(/\s+/g, ' ') || 'Almost Famous'; input.value = name; const mood = moods[$('#brand-mood').value]; const safe = escapeXml(name); const size = name.length > 20 ? 33 : name.length > 14 ? 42 : name.length > 9 ? 50 : 65; brandSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 460" role="img" aria-label="${safe} logo"><rect width="600" height="460" fill="${mood.bg}"/><g fill="${mood.fg}"><path d="m300 56 15 40 43-15-27 33 27 33-43-15-15 40-15-40-43 15 27-33-27-33 43 15Z"/><text x="300" y="259" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-size="${size}" font-weight="700" letter-spacing="-2">${safe}</text><text x="300" y="306" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-size="12" letter-spacing="3">${mood.tag}</text><path d="M45 379h510" stroke="${mood.fg}" stroke-opacity=".4"/><text x="45" y="411" font-family="Arial,Helvetica,sans-serif" font-size="9" letter-spacing="1.5">JAYNOVA BRAND LAB / ORIGINAL DEMO</text><text x="555" y="411" text-anchor="end" font-family="Arial,Helvetica,sans-serif" font-size="9">NO TRADEMARK CLEARANCE</text></g></svg>`; $('#brand-preview').innerHTML = brandSvg; brandCaption = `${name} ${mood.caption}`; $('#brand-caption').textContent = brandCaption; $('#lab-status').textContent = 'Your new era is ready.'; }
$$('[data-open-lab]').forEach(button => button.addEventListener('click', () => { generateBrand(); showDialog($('#lab-dialog')); }));
$('#brand-form').addEventListener('submit', event => { event.preventDefault(); generateBrand(); });
$('#download-brand').addEventListener('click', () => { const slug = $('#brand-name').value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'your-brand'; downloadFile(`${slug}-jaynova.svg`, brandSvg, 'image/svg+xml'); $('#lab-status').textContent = 'Logo downloaded. Big-brand energy unlocked.'; });
$('#copy-caption').addEventListener('click', async () => { try { await navigator.clipboard.writeText(brandCaption); $('#lab-status').textContent = 'Caption copied. Go be a little extra.'; } catch { $('#lab-status').textContent = 'Select the caption above to copy it manually.'; } });
$$('[data-open-notice]').forEach(button => button.addEventListener('click', () => showDialog($('#notice-dialog'))));
